INSERT INTO public.situations (id, libelle, nom_technique, created_at, updated_at, questionnaire_id, questionnaire_entrainement_id, deleted_at, description) VALUES
	('40c3b25b-6d5b-45e6-a645-7026b3db3ed5', 'Prévention', 'prevention', '2020-01-28 16:37:48.195409', '2020-01-28 16:37:48.195409', NULL, NULL, NULL, NULL),
	('0cdbc5b9-aa48-4587-844d-86965dc67709', 'Maintenance', 'maintenance', '2020-02-03 17:20:29.67025', '2020-02-03 17:20:29.67025', NULL, NULL, NULL, 'Compétences de base. Ce module, basé sur une activité de décision lexicale, permet de tester la connaissance du vocabulaire en français.'),
	('569cdc17-554d-4227-acfe-1d5d3a4afdbc', 'Livraison', 'livraison', '2020-02-11 15:49:40.88873', '2023-05-11 15:48:08.679042', '128b79f8-fcfb-4e63-88e8-991047af3a70', '9a840233-3066-46e0-bae9-5ba129436241', NULL, 'Compétences de base. Ce module propose plusieurs tests des compétences langagières et mathématiques. Si l''exercice de rédaction est sélectionné, un extrait de production écrite est également collecté.'),
	('56950c03-d386-4918-bc41-11800078fd8e', 'Tri', 'tri', '2019-07-08 12:38:53.45583', '2019-09-06 13:35:35.794152', NULL, NULL, NULL, 'Compétences transversales. Ce module ludique permet de tester les bénéficiaires sur leur capacité à comparer et trier, ainsi que sur leur vitesse d''exécution.'),
	('8cf7d02b-4806-4d2c-ac05-ee5828ef19ef', 'Contrôle', 'controle', '2019-07-08 12:38:40.448988', '2019-09-06 13:35:43.174545', NULL, NULL, NULL, 'Compétences transversales. Ce module invite les bénéficiaires à faire preuve d''attention, de concentration, de vitesse d''exécution pour réaliser une tâche répétitive dans un environnement d''usine.'),
	('e05619a7-ea29-49ba-8aeb-962c01b34d3b', 'Sécurité', 'securite', '2019-10-16 09:20:39.353119', '2019-10-16 09:20:39.353119', NULL, NULL, NULL, 'Compétences transversales. Ce module demande aux bénéficiaires d''identifier et de qualifier des situations dangereuses sur un chantier. Les capacités d''attention, de vigilance et de contrôle sont sollicitées.'),
	('50d7cdae-46de-43d5-8f20-73912ee5c6d8', 'Objets trouvés', 'objets_trouves', '2020-03-25 15:47:14.349347', '2020-03-25 15:47:14.349347', NULL, NULL, NULL, 'Compétences de base. Ce module propose aux bénéficiaires des énigmes à résoudre pour restituer un téléphone perdu. Les compétences langagières et mathématiques sont testées.'),
	('cd8bbc27-62e6-4a4f-b383-a5bcc2cd5d7a', 'Inventaire', 'inventaire', '2019-07-08 12:38:40.251746', '2019-09-06 13:35:52.078745', NULL, NULL, NULL, 'Compétences transversales. Ce module demande aux bénéficiaires de faire preuve de méthode, de vigilance, de contrôle et de vitesse pour réaliser une tâche d''inventaire.'),
	('b6c10f31-2212-43b8-8121-7dc5a8937698', 'Café de la place', 'cafe_de_la_place', '2023-01-26 15:35:05.194586', '2023-01-26 15:35:05.194586', NULL, NULL, NULL, 'Compétences langagières - Avancé. Ce module adaptatif complet permet d''évaluer la maîtrise globale des compétences langagières (lecture et identification de mots, compréhension d''information écrite, orthographe, accords et conjugaison, etc.)'),
	('aaf3af21-06d6-491e-8d7f-83a8afd72770', 'Place du marché', 'place_du_marche', '2023-01-26 15:35:05.194586', '2023-01-26 15:35:05.194586', NULL, NULL, NULL, 'Compétences Numerique'),
	('e74239ba-7fd1-41d0-9dc4-436c27165ff0', 'Plan de la ville', 'plan_de_la_ville', '2021-12-10 15:41:24.721733', '2021-12-10 15:41:24.721733', NULL, NULL, NULL, 'Ce module permet de vérifier que les manipulations indispensables pour utiliser eva, sur ordinateur ou sur tablette, sont bien maîtrisées.');
INSERT INTO public.situations (id, libelle, nom_technique, created_at, updated_at, questionnaire_id, questionnaire_entrainement_id, deleted_at, description) VALUES
	('2d154cbd-a422-43bf-8534-1538b6d1b8c5', 'Bienvenue', 'bienvenue', '2020-04-28 09:06:56.511198', '2024-08-19 13:45:47.847887', 'af35ed6b-0011-4250-9a98-ac544657af8c', NULL, NULL, 'Ce module collecte des informations utiles pour l''accompagnement des bénéficiaires et, si l''auto-positionnement est sélectionné, interroge ces derniers sur leur maîtrise des compétences transversales.');
